mapper.select:
SELECT a.ASSET_ID, a.ASSET_CODE, a.ASSET_NAME, a.CATEGORY_ID, a.ORIGINAL_VALUE, a.RESIDUAL_VALUE, a.ACCUMULATED_DEPRECIATION, a.NET_VALUE, a.DEPRECIATION_METHOD, a.USEFUL_LIFE, a.DEPT_ID, a.RESPONSIBLE_PERSON, a.PURCHASE_DATE, a.START_DEPRECIATION_DATE, a.STATUS, a.SPECIFICATION, a.MANUFACTURER, a.SUPPLIER, a.LOCATION, a.REMARK, a.TENANT_ID, a.CREATE_BY, a.CREATE_TIME, a.UPDATE_BY, a.UPDATE_TIME, a.IS_DELETED, c.CATEGORY_NAME AS categoryName, d.ORGNAME AS deptName FROM TBL_FIXED_ASSET_CARD a LEFT JOIN TBL_FIXED_ASSET_CATEGORY c ON a.CATEGORY_ID = c.CATEGORY_ID AND c.IS_DELETED = 0 LEFT JOIN TBL_ORGANIZATION d ON a.DEPT_ID = d.ORGID AND (d.STATUS IS NULL OR d.STATUS = 0) WHERE a.IS_DELETED = 0
AND a.TENANT_ID = #{param.tenantId}
AND a.ASSET_CODE LIKE '%' || #{param.assetCode} || '%'
AND a.ASSET_NAME LIKE '%' || #{param.assetName} || '%'
AND a.CATEGORY_ID = #{param.categoryId}
AND a.DEPT_ID = #{param.deptId}
AND a.STATUS = #{param.status}
AND a.RESPONSIBLE_PERSON LIKE '%' || #{param.responsiblePerson} || '%'
AND a.PURCHASE_DATE >= #{param.purchaseDateStart}
AND a.PURCHASE_DATE <= #{param.purchaseDateEnd}
ORDER BY a.CREATE_TIME DESC

SELECT c.CATEGORY_ID AS categoryId, c.CATEGORY_NAME AS categoryName, COUNT(a.ASSET_ID) AS assetCount, NVL(SUM(a.ORIGINAL_VALUE), 0) AS totalOriginalValue, NVL(SUM(a.NET_VALUE), 0) AS totalNetValue FROM TBL_FIXED_ASSET_CATEGORY c LEFT JOIN TBL_FIXED_ASSET_CARD a ON c.CATEGORY_ID = a.CATEGORY_ID AND a.IS_DELETED = 0 WHERE c.IS_DELETED = 0
AND c.TENANT_ID = #{tenantId}
GROUP BY c.CATEGORY_ID, c.CATEGORY_NAME ORDER BY totalOriginalValue DESC
